let walkFrames = [];
let pushFrames = [];
let magicFrames = [];
let jumpFrames = [];
let animation = "idle";
let frameIndex = 0;
let lastFrameTime = 0;
let animationStartTime = 0;
let worldX = 0; // 人物在世界裡走了多遠,背景會依此滾動
let movementDirection = 1;
let idleFrame;
let backgroundImage;
const activeKeys = new Set();

// ===== 角色2 設定 =====
// 兩張精靈圖已內嵌在檔案最下方（CHAR2_WALK_DATA / CHAR2_ATTACK_DATA），不需要另外放圖檔
const CHAR2_WALK_COUNT = 6;
const CHAR2_ATTACK_COUNT = 8;
const char2Height = 150;       // 角色2 畫在畫面上的高度
const char2Speed = 130;        // 角色2 移動速度
const touchDistanceX = 70;     // 水平方向小於這個距離算「碰到」
const touchDistanceY = 45;     // 垂直方向小於這個距離算「碰到」
let char2WalkSheet, char2AttackSheet;
let char2WalkFrames = [], char2AttackFrames = [];
const char2 = {
  worldX: 320,        // 角色2 在世界裡的位置（跟背景一起捲動）
  yOffset: 0,         // 相對地面的上下偏移（上下鍵控制）
  direction: -1,      // 1 = 面向右，-1 = 面向左
  moving: false,
  frameIndex: 0,
  lastFrameTime: 0,
  cooldownUntil: 0    // 答對後的短暫無敵時間，避免立刻又觸發
};

// ===== 戰鬥 / 數學題 =====
// 戰鬥流程：intro（原角色放 magic）→ quiz（答題）
//   答對 → heroMagic（原角色再放 magic，角色2 被擊中）→ 結束
//   答錯 → char2Attack（角色2 attack，原角色被擊中）→ 回到 quiz 換一題
const MAGIC_FRAME_MS = 130;        // magic 每格停留時間
const HIT_MS = 600;                // 被擊中特效持續時間
const MAGIC_CUTS = [[0, 165], [165, 352], [352, 576], [576, 899], [899, 1232]]; // magic.png 五格的切割位置
const MAGIC_BODY_HEIGHT = 174;     // magic 第一格人物高度（用來對齊大小）
const MAGIC_BODY_HALF = 85;        // 人物身體寬度的一半（用來對齊位置）
let heroMagicSheet, heroMagicFrames = [];
let battleActive = false;
let battlePhase = null;
let phaseStart = 0;
let heroHitStart = -99999;         // 原角色被擊中的開始時間
let char2HitStart = -99999;        // 角色2 被擊中的開始時間
let quizLocked = false;            // 已作答、等待下一步時不能再按
// ===== 英文常識題庫（q = 題目，a = 正確答案，wrong = 三個錯誤選項）=====
// 想加題目就照格式新增一行；題目會洗牌後依序抽，抽完再重洗
const QUIZ_BANK = [
  { q: "What is the chemical symbol for gold?", a: "Au", wrong: ["Ag", "Gd", "Go"] },
  { q: "Who painted the Mona Lisa?", a: "Leonardo da Vinci", wrong: ["Michelangelo", "Raphael", "Vincent van Gogh"] },
  { q: "What is the capital of Australia?", a: "Canberra", wrong: ["Sydney", "Melbourne", "Perth"] },
  { q: "Which element has the atomic number 1?", a: "Hydrogen", wrong: ["Helium", "Oxygen", "Carbon"] },
  { q: "In which year did World War II end?", a: "1945", wrong: ["1939", "1918", "1950"] },
  { q: "Which is the longest river in South America?", a: "Amazon River", wrong: ["Orinoco River", "Paraná River", "Magdalena River"] },
  { q: "What is the smallest prime number?", a: "2", wrong: ["0", "1", "3"] },
  { q: "Who developed the theory of general relativity?", a: "Albert Einstein", wrong: ["Isaac Newton", "Niels Bohr", "Galileo Galilei"] },
  { q: "Which is the largest desert in the world?", a: "Antarctic Desert", wrong: ["Sahara Desert", "Gobi Desert", "Arabian Desert"] },
  { q: "Which language has the most native speakers?", a: "Mandarin Chinese", wrong: ["English", "Spanish", "Hindi"] },
  { q: "What is the hardest natural substance?", a: "Diamond", wrong: ["Quartz", "Granite", "Iron"] },
  { q: "Which country has the largest land area?", a: "Russia", wrong: ["Canada", "China", "United States"] },
  { q: "Who was the first person to walk on the Moon?", a: "Neil Armstrong", wrong: ["Buzz Aldrin", "Yuri Gagarin", "John Glenn"] },
  { q: "What is the currency of Japan?", a: "Yen", wrong: ["Won", "Yuan", "Ringgit"] },
  { q: "Which scientist discovered penicillin?", a: "Alexander Fleming", wrong: ["Louis Pasteur", "Marie Curie", "Joseph Lister"] },
  { q: "About how fast does light travel?", a: "300,000 km per second", wrong: ["30,000 km per second", "3,000 km per second", "3,000,000 km per second"] },
  { q: "How many bones are in an adult human body?", a: "206", wrong: ["156", "256", "306"] },
  { q: "Which city hosted the 2008 Summer Olympics?", a: "Beijing", wrong: ["Athens", "London", "Sydney"] },
  { q: "What is the capital of Canada?", a: "Ottawa", wrong: ["Toronto", "Vancouver", "Montreal"] },
  { q: "Who wrote the novel \"1984\"?", a: "George Orwell", wrong: ["Aldous Huxley", "Ray Bradbury", "H. G. Wells"] },
  { q: "Which gas makes up most of Earth's atmosphere?", a: "Nitrogen", wrong: ["Oxygen", "Carbon dioxide", "Argon"] },
  { q: "Which mountain is the highest above sea level?", a: "Mount Everest", wrong: ["K2", "Kilimanjaro", "Mont Blanc"] },
  { q: "What does \"CPU\" stand for?", a: "Central Processing Unit", wrong: ["Central Program Utility", "Computer Personal Unit", "Core Processing Update"] },
  { q: "Who wrote \"Pride and Prejudice\"?", a: "Jane Austen", wrong: ["Charlotte Brontë", "Mary Shelley", "Emily Dickinson"] },
  { q: "Which blood type is called the universal red-cell donor?", a: "O negative", wrong: ["AB positive", "A positive", "B negative"] },
  { q: "The Great Barrier Reef lies off the coast of which country?", a: "Australia", wrong: ["Brazil", "Mexico", "Indonesia"] },
  { q: "What is the capital of Turkey?", a: "Ankara", wrong: ["Istanbul", "Izmir", "Antalya"] },
  { q: "Which vitamin does sunlight help your body make?", a: "Vitamin D", wrong: ["Vitamin C", "Vitamin A", "Vitamin B12"] },
  { q: "Who composed \"The Four Seasons\"?", a: "Antonio Vivaldi", wrong: ["Wolfgang Mozart", "Johann Bach", "Ludwig Beethoven"] },
  { q: "Which part of a cell produces most of its energy?", a: "Mitochondria", wrong: ["Nucleus", "Ribosome", "Golgi apparatus"] }
];
let quizDeck = [];
let quizAnswer = "";
let quizValues = [];
let quizScore = 0;
let quizBox, quizQuestionEl, quizOptionsEl, quizMsgEl;

const frameDuration = 100;
const characterFrameSize = 160;
const movementSpeed = 120;
const groundRatio = 0.9; // 腳底站在畫面高度的 90% 處(草地上)

function preload() {
  // 背景圖已經直接內嵌在這個檔案最下方,不需要另外放 background.png
  backgroundImage = loadImage(BACKGROUND_DATA);
  walkFrames = loadFrames("walk", 6);
  pushFrames = loadFrames("push", 6, 5);
  magicFrames = loadFrames("magic", 5);
  jumpFrames = loadFrames("jump", 13);
  char2WalkSheet = loadImage(CHAR2_WALK_DATA);
  char2AttackSheet = loadImage(CHAR2_ATTACK_DATA);
  heroMagicSheet = loadImage(HERO_MAGIC_DATA);
}

function loadFrames(animationName, frameCount, firstFrame = 0) {
  return Array.from({ length: frameCount }, (_, index) =>
    loadImage(`111/${animationName}/${index + firstFrame}.png`)
  );
}

function setup() {
  createCanvas(windowWidth, windowHeight);
  imageMode(CENTER);
  idleFrame = walkFrames[0];
  char2WalkFrames = sliceSheet(char2WalkSheet, CHAR2_WALK_COUNT);
  char2AttackFrames = sliceSheet(char2AttackSheet, CHAR2_ATTACK_COUNT);
  heroMagicFrames = MAGIC_CUTS.map(([x0, x1]) =>
    heroMagicSheet.get(x0, 0, x1 - x0, heroMagicSheet.height)
  );
  createQuizUI();
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

function draw() {
  drawBackground();

  const now = millis();
  // 人物固定在畫面中央,走路時是背景在滾動
  if ((animation === "walk" || animation === "push") && !battleActive) {
    worldX += movementDirection * movementSpeed * min(deltaTime, 50) / 1000;
  }

  const frames = getAnimationFrames();

  if (animation !== "idle" && now - lastFrameTime >= frameDuration) {
    lastFrameTime = now;

    if (frameIndex < frames.length - 1) {
      frameIndex++;
    } else if (animation === "walk" || (animation === "push" && activeKeys.has("j"))) {
      frameIndex = 0;
    } else {
      idleFrame = walkFrames[0];
      animation = "idle";
      frameIndex = 0;
    }
  }

  updateBattle(now);

  const currentFrame = animation === "idle"
    ? idleFrame
    : getAnimationFrames()[frameIndex];
  const frameScale = min(characterFrameSize / currentFrame.width,
    characterFrameSize / currentFrame.height);
  const frameWidth = currentFrame.width * frameScale;
  const frameHeight = currentFrame.height * frameScale;
  const jumpProgress = constrain(
    (now - animationStartTime) / (frameDuration * (jumpFrames.length - 1)),
    0,
    1
  );
  const jumpOffset = animation === "jump"
    ? sin(PI * jumpProgress) * characterFrameSize * 0.6
    : 0;
  // 角色2：更新位置/碰撞，腳底比較高的先畫（在後面）
  const heroFeetY = height * groundRatio - jumpOffset;
  updateChar2(heroFeetY);
  const char2Behind = char2FeetY() <= heroFeetY;
  if (char2Behind) drawChar2();

  // 原角色：戰鬥時放 magic；被角色2 擊中時變紅、抖動、被打退
  const heroInMagic = battlePhase === "intro" || battlePhase === "heroMagic";
  const heroHitT = (now - heroHitStart) / HIT_MS;
  const heroHit = heroHitT >= 0 && heroHitT < 1;
  const heroOffsetX = heroHit
    ? random(-6, 6) * (1 - heroHitT) - movementDirection * 40 * sin(PI * heroHitT)
    : 0;

  if (heroInMagic) {
    drawHeroMagic(now, heroOffsetX);
  } else {
    push();
    translate(width / 2 + heroOffsetX, height * groundRatio - frameHeight / 2 - jumpOffset);
    scale(movementDirection, 1);
    if (heroHit) tint(255, 90, 90);
    image(currentFrame, 0, 0, frameWidth, frameHeight);
    noTint();
    pop();
  }

  if (!char2Behind) drawChar2();
  drawEffects(now);
  drawHud();
}

function drawBackground() {
  // 背景圖沒載入成功時,退回天藍色,程式仍可執行
  if (!backgroundImage || !backgroundImage.width) {
    background(135, 206, 235);
    return;
  }

  // 圖片高度剛好等於畫面高度,左右用同一張圖一直接下去
  const tileWidth = backgroundImage.width * (height / backgroundImage.height);
  const firstTile = Math.floor((worldX - width / 2) / tileWidth);
  const lastTile = Math.floor((worldX + width / 2) / tileWidth);

  noSmooth(); // 像素風背景保持清晰
  for (let i = firstTile; i <= lastTile; i++) {
    // 每隔一張左右翻轉,相鄰的邊緣才會剛好接起來
    const flipped = ((i % 2) + 2) % 2 === 1;
    const left = Math.floor(i * tileWidth - worldX + width / 2);
    const w = Math.ceil(tileWidth) + 1; // 多 1 像素避免接縫出現細線

    push();
    translate(left + w / 2, height / 2);
    if (flipped) scale(-1, 1);
    image(backgroundImage, 0, 0, w, height);
    pop();
  }
  smooth();
}

function getAnimationFrames() {
  if (animation === "walk") return walkFrames;
  if (animation === "push") return pushFrames;
  if (animation === "magic") return magicFrames;
  if (animation === "jump") return jumpFrames;
  return walkFrames;
}

function keyPressed() {
  // 方向鍵給角色2 用，避免網頁跟著捲動
  if (keyCode >= 37 && keyCode <= 40) return false;

  // 戰鬥中：只能用 1/2/3 回答，原角色不能操作
  if (battleActive) {
    const n = parseInt(key, 10);
    if (n >= 1 && n <= quizValues.length) chooseAnswer(quizValues[n - 1]);
    return false;
  }

  const pressedKey = getPressedKey();
  const animationName = getAnimationForKey(pressedKey);

  if (!animationName || activeKeys.has(pressedKey)) return;

  activeKeys.add(pressedKey);
  startKeyAnimation(pressedKey);
}

function keyReleased() {
  const releasedKey = getPressedKey();
  if (!activeKeys.delete(releasedKey)) return;
  if (animation === "push" || animation === "magic") return;

  if (animation === "jump") {
    if (releasedKey !== "space") return;
    if (activeKeys.size === 0) {
      stopAnimation();
    } else {
      startKeyAnimation(Array.from(activeKeys).pop());
    }
    return;
  }

  if (activeKeys.size === 0) {
    stopAnimation();
    return;
  }

  startKeyAnimation(Array.from(activeKeys).pop());
}

function getPressedKey() {
  return keyCode === 32 ? "space" : key.toLowerCase();
}

function getAnimationForKey(pressedKey) {
  if (pressedKey === "a" || pressedKey === "d") return "walk";
  if (pressedKey === "j") return "push";
  if (pressedKey === "k") return "magic";
  if (pressedKey === "space") return "jump";
  return null;
}

function startKeyAnimation(pressedKey) {
  if (pressedKey === "a") movementDirection = -1;
  if (pressedKey === "d") movementDirection = 1;
  startAnimation(getAnimationForKey(pressedKey));
}

// ===== 角色2 =====
// 把一整張橫向精靈圖平均切成 count 格
function sliceSheet(sheet, count) {
  const frameW = sheet.width / count;
  return Array.from({ length: count }, (_, i) => {
    const x0 = Math.round(i * frameW);
    const x1 = Math.round((i + 1) * frameW);
    return sheet.get(x0, 0, x1 - x0, sheet.height);
  });
}

function char2ScreenX() {
  return width / 2 + (char2.worldX - worldX);
}

function char2FeetY() {
  return height * groundRatio + char2.yOffset;
}

function updateChar2(heroFeetY) {
  const now = millis();
  const dt = min(deltaTime, 50) / 1000;
  char2.moving = false;

  if (!battleActive) {
    // 方向鍵 ↑ ↓ ← → 控制角色2
    let dx = 0;
    let dy = 0;
    if (keyIsDown(LEFT_ARROW)) dx -= 1;
    if (keyIsDown(RIGHT_ARROW)) dx += 1;
    if (keyIsDown(UP_ARROW)) dy -= 1;
    if (keyIsDown(DOWN_ARROW)) dy += 1;

    if (dx !== 0 || dy !== 0) {
      const len = Math.hypot(dx, dy);
      char2.worldX += (dx / len) * char2Speed * dt;
      char2.yOffset = constrain(
        char2.yOffset + (dy / len) * char2Speed * 0.6 * dt,
        -height * 0.15,
        height * 0.07
      );
      if (dx !== 0) char2.direction = dx;
      char2.moving = true;
    }

    // 原有角色碰到角色2 → 開始戰鬥
    if (
      now > char2.cooldownUntil &&
      abs(char2ScreenX() - width / 2) < touchDistanceX &&
      abs(char2FeetY() - heroFeetY) < touchDistanceY
    ) {
      startBattle();
    }
  }

  // 動畫換格：答錯時播放一次 attack；走動時播放 walk；其餘停在站立第一格
  if (battlePhase === "char2Attack") {
    char2.frameIndex = constrain(
      floor((now - phaseStart) / frameDuration),
      0,
      char2AttackFrames.length - 1
    );
  } else if (!battleActive && char2.moving) {
    if (now - char2.lastFrameTime >= frameDuration) {
      char2.lastFrameTime = now;
      char2.frameIndex = (char2.frameIndex + 1) % char2WalkFrames.length;
    }
  } else {
    char2.frameIndex = 0;
  }
}

function drawChar2() {
  const frames = battlePhase === "char2Attack" ? char2AttackFrames : char2WalkFrames;
  const img = frames[char2.frameIndex % frames.length];
  const scaleRatio = char2Height / img.height;
  const w = img.width * scaleRatio;
  const h = img.height * scaleRatio;
  const x = char2ScreenX();
  if (x < -w || x > width + w) return;   // 在畫面外就不畫

  const hitT = (millis() - char2HitStart) / HIT_MS;
  const hit = hitT >= 0 && hitT < 1;
  const shakeX = hit ? random(-6, 6) * (1 - hitT) : 0;

  noSmooth(); // 像素風精靈圖保持清晰
  push();
  translate(x + shakeX, char2FeetY() - h / 2);
  scale(char2.direction, 1);
  if (hit) tint(255, 110, 110);
  image(img, 0, 0, w, h);
  noTint();
  pop();
  smooth();
}

// 原角色放 magic：用腳底對齊地面、身體對齊中心，特效（弧光）往面向的方向延伸
function drawHeroMagic(now, offsetX) {
  const index = constrain(floor((now - phaseStart) / MAGIC_FRAME_MS), 0, heroMagicFrames.length - 1);
  const img = heroMagicFrames[index];
  const s = characterFrameSize / MAGIC_BODY_HEIGHT;
  push();
  translate(width / 2 + offsetX, height * groundRatio);
  scale(movementDirection, 1);
  imageMode(CORNER);
  image(img, -MAGIC_BODY_HALF * s, -img.height * s, img.width * s, img.height * s);
  pop();
  imageMode(CENTER);
}

// 被擊中特效：擴散圓環 + 放射線 + 文字，t 從 0 到 1
function drawBurst(x, y, t, label) {
  const fade = 255 * (1 - t);
  push();
  translate(x, y);
  noFill();
  stroke(255, 190, 40, fade);
  strokeWeight(8 * (1 - t) + 1);
  circle(0, 0, 40 + 150 * t);
  stroke(255, 255, 255, fade);
  strokeWeight(3);
  for (let i = 0; i < 10; i++) {
    const angle = (i * TWO_PI) / 10 + 0.3;
    const r1 = 30 + 70 * t;
    const r2 = r1 + 14 + 26 * (1 - t);
    line(cos(angle) * r1, sin(angle) * r1, cos(angle) * r2, sin(angle) * r2);
  }
  noStroke();
  fill(255, 240, 120, fade);
  circle(0, 0, 50 * (1 - t));
  textAlign(CENTER, CENTER);
  textSize(34);
  stroke(0, fade);
  strokeWeight(5);
  fill(255, 70, 70, fade);
  text(label, 0, -110 - 30 * t);
  pop();
}

function drawEffects(now) {
  const heroT = (now - heroHitStart) / HIT_MS;
  if (heroT >= 0 && heroT < 1) {
    push();
    noStroke();
    fill(255, 0, 0, 70 * (1 - heroT));   // 畫面短暫泛紅
    rect(0, 0, width, height);
    pop();
    drawBurst(width / 2, height * groundRatio - 90, heroT, "被擊中！");
  }
  const char2T = (now - char2HitStart) / HIT_MS;
  if (char2T >= 0 && char2T < 1) {
    drawBurst(char2ScreenX(), char2FeetY() - 80, char2T, "HIT!");
  }
}

function drawHud() {
  push();
  textAlign(LEFT, TOP);
  textSize(18);
  stroke(0);
  strokeWeight(4);
  fill(255);
  text("角色2：↑ ↓ ← → 移動　原角色：A / D 走路", 16, 14);
  text("答對題數：" + quizScore, 16, 40);
  pop();
}

// ===== 戰鬥：magic / attack + 數學題 =====
function startBattle() {
  battleActive = true;
  activeKeys.clear();
  stopAnimation();                                   // 原角色停下來
  movementDirection = char2ScreenX() > width / 2 ? 1 : -1; // 原角色面向角色2
  char2.direction = -movementDirection;              // 角色2 面向原角色
  char2.frameIndex = 0;
  newQuestion();                                     // 先準備好題目（還不顯示）
  quizBox.style.display = "none";
  battlePhase = "intro";                             // 遇到角色2 → 原角色先放 magic
  phaseStart = millis();
}

// 每個畫面更新一次：切換戰鬥階段、觸發特效
function updateBattle(now) {
  if (!battlePhase) return;
  const t = now - phaseStart;
  const magicTotal = MAGIC_FRAME_MS * heroMagicFrames.length;

  if (battlePhase === "intro") {
    if (t >= magicTotal + 150) {
      battlePhase = "quiz";
      quizBox.style.display = "block";
    }
  } else if (battlePhase === "heroMagic") {
    // 弧光出現的那一格，角色2 被擊中
    if (t >= MAGIC_FRAME_MS * 3 && char2HitStart < phaseStart) char2HitStart = now;
    if (t >= magicTotal + 300) endBattle();
  } else if (battlePhase === "char2Attack") {
    // 角色2 踢出去的那一格，原角色被擊中
    if (t >= frameDuration * 4 && heroHitStart < phaseStart) heroHitStart = now;
    if (t >= frameDuration * char2AttackFrames.length + 300) {
      newQuestion();
      quizMsgEl.textContent = "Wrong! Character 2 hit you. Try another one!";
      battlePhase = "quiz";
      quizBox.style.display = "block";
    }
  }
}

function endBattle() {
  quizBox.style.display = "none";
  battleActive = false;
  battlePhase = null;
  char2.frameIndex = 0;
  // 把角色2 彈開一段距離，並給 1.5 秒冷卻
  const away = char2ScreenX() > width / 2 ? 1 : -1;
  char2.worldX += away * 220;
  char2.cooldownUntil = millis() + 1500;
}

function newQuestion() {
  quizLocked = false;
  if (quizDeck.length === 0) quizDeck = shuffle(QUIZ_BANK.slice());
  const item = quizDeck.pop();
  quizAnswer = item.a;
  quizQuestionEl.textContent = item.q;
  quizValues = shuffle([item.a, ...item.wrong]);

  quizOptionsEl.innerHTML = "";
  quizValues.forEach((v, i) => {
    const btn = document.createElement("button");
    btn.textContent = (i + 1) + ". " + v;
    btn.style.cssText =
      "display:block;width:100%;margin:6px 0;font-size:18px;padding:8px 16px;" +
      "border-radius:8px;border:2px solid #888;background:#fff;color:#222;cursor:pointer;";
    btn.onclick = () => chooseAnswer(v);
    quizOptionsEl.appendChild(btn);
  });
  quizMsgEl.textContent = "Press 1 / 2 / 3 / 4 or click an answer";
}

function chooseAnswer(value) {
  if (battlePhase !== "quiz" || quizLocked) return;
  quizLocked = true;
  quizBox.style.display = "none";        // 收起題目，讓動畫看得清楚
  phaseStart = millis();
  if (value === quizAnswer) {
    quizScore++;
    battlePhase = "heroMagic";           // 答對 → 原角色放 magic
  } else {
    battlePhase = "char2Attack";         // 答錯 → 角色2 attack，原角色被擊中
  }
}

function createQuizUI() {
  quizBox = document.createElement("div");
  quizBox.style.cssText =
    "position:fixed;left:50%;top:32%;transform:translate(-50%,-50%);" +
    "display:none;background:rgba(255,255,255,.95);color:#222;" +
    "border:3px solid #d9480f;border-radius:14px;padding:18px 26px;" +
    "text-align:center;font-family:sans-serif;z-index:10;min-width:320px;max-width:90vw;";

  const title = document.createElement("div");
  title.textContent = "Battle! Answer correctly to escape";
  title.style.cssText = "font-size:16px;margin-bottom:6px;";

  quizQuestionEl = document.createElement("div");
  quizQuestionEl.style.cssText = "font-size:26px;font-weight:700;margin:6px 0 14px;";

  quizOptionsEl = document.createElement("div");

  quizMsgEl = document.createElement("div");
  quizMsgEl.style.cssText = "min-height:22px;margin-top:12px;font-size:15px;";

  [title, quizQuestionEl, quizOptionsEl, quizMsgEl].forEach(el => quizBox.appendChild(el));
  document.body.appendChild(quizBox);
}

function stopAnimation() {
  idleFrame = walkFrames[0];
  animation = "idle";
  frameIndex = 0;
}

function startAnimation(animationName) {
  animation = animationName;
  frameIndex = 0;
  lastFrameTime = millis();
  animationStartTime = lastFrameTime;
}

